// Generated bytes are checked in, so ordinary builds need no toolchain.
// Regenerate with the pinned Zig, which compiles compress.zig and, with its
// clang, zlib and the LZMA SDK, unchanged, to wasm32-freestanding; --check
// verifies their inputs.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { copyFileSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const here = fileURLToPath(new URL(".", import.meta.url));
const zlib = fileURLToPath(new URL("../../vendor/zlib/", import.meta.url));
const sdk = fileURLToPath(new URL("../../vendor/lzma-sdk/", import.meta.url));
const lzma = join(sdk, "C");

const ZIG_VERSION = "0.17.0";
/** The release's tarballs, from ziglang.org/download/index.json. */
const ZIG_SHA256: Record<string, string> = {
  "x86_64-linux": "1cbe9df9f27e6b78d14ccbca43b6703a404ef79ef1c463de901d7f088d4e2026",
  "aarch64-linux": "9e8d11661d4ae3bd57702a3832781e23ad151dde5798e16a5ccd503f65234ff8",
};

const zlibSources = ["adler32", "deflate", "inflate", "inftrees", "inffast", "trees", "zutil"];
const zlibHeaders = ["zlib", "zconf", "zutil", "deflate", "inflate", "inftrees", "inffast"];
const sdkSources = ["LzmaEnc", "LzFind", "LzmaDec"];
const sdkHeaders = ["LzmaEnc", "LzFind", "LzmaDec", "LzHash", "7zTypes", "Compiler", "CpuArch"];
const sources = [
  ...zlibSources.map((name) => join(zlib, `${name}.c`)),
  ...sdkSources.map((name) => join(lzma, `${name}.c`)),
];
const inputs = [
  fileURLToPath(import.meta.url),
  join(here, "compress.zig"),
  ...sources,
  ...["string.h", "stdlib.h", "errno.h"].map((name) => join(here, "include", name)),
  ...zlibHeaders.map((name) => join(zlib, `${name}.h`)),
  join(zlib, "inffixed.h"),
  join(zlib, "trees.h"),
  ...sdkHeaders.map((name) => join(lzma, `${name}.h`)),
  join(lzma, "Precomp.h"),
  join(zlib, "LICENSE"),
];
const exports = [
  "reset",
  "alloc",
  "resultPointer",
  "resultSize",
  "inputUsed",
  "errorMessage",
  "inflateData",
  "deflateData",
  "lzmaDecode",
  "lzmaEncode",
];
const cflags = [
  "-O2",
  "-mbulk-memory",
  "-fno-stack-protector",
  // zlib without its own allocator or gzip, the SDK without threads.
  "-DZ_SOLO",
  "-DNO_GZIP",
  "-DHAVE_MEMCPY",
  "-DZ7_ST",
  // Z_SOLO keeps zlib from including string.h, whose functions it still calls.
  "-include",
  join(here, "include/string.h"),
];
// For the C and for the headers translated for compress.zig alike: the
// libraries' headers, and include/'s declarations of the libc functions
// that Zig's compiler-rt defines.
const includes = [join(here, "include"), zlib, lzma].flatMap((dir) => ["-I", dir]);
/** What compress.zig imports as "c", translated in the build: Zig 0.17 has no @cImport. */
const translated = '#include "zlib.h"\n#include "LzmaEnc.h"\n#include "LzmaDec.h"\n';

const digest = createHash("sha256").update(ZIG_VERSION);
for (const file of inputs) {
  digest.update(readFileSync(file));
}

const inputDigest = digest.digest("hex");
const target = join(here, "src/binary.ts");
if (process.argv.includes("--check")) {
  if (!readFileSync(target, "utf8").includes(`inputs: ${inputDigest}`)) {
    throw new Error("compression inputs changed; run pnpm --filter @swf2es/compress build:wasm");
  }
} else {
  const zig = findZig();
  const work = join(tmpdir(), `swf2es-compress-${process.pid}`);
  mkdirSync(work, { recursive: true });
  try {
    const out = join(work, "compress.wasm");
    const caches = ["--cache-dir", join(work, "cache"), "--global-cache-dir", join(work, "global")];
    const wasm32 = ["-target", "wasm32-freestanding"];
    writeFileSync(join(work, "c.h"), translated);
    const c = execFileSync(zig, [
      "translate-c",
      ...wasm32,
      ...includes,
      "-DZ_SOLO",
      "-DZ7_ST",
      join(work, "c.h"),
      ...caches,
    ]);
    writeFileSync(join(work, "c.zig"), c);
    const flags = [...wasm32, "-mcpu=generic+bulk_memory", "-O", "ReleaseFast"];
    execFileSync(
      zig,
      [
        "build-exe",
        ...flags,
        "-fsingle-threaded",
        "-fno-entry",
        "-fstrip",
        "--stack",
        "131072",
        ...exports.map((name) => `--export=${name}`),
        ...includes,
        "-cflags",
        ...cflags,
        "--",
        ...sources,
        "--dep",
        "c",
        `-Mroot=${join(here, "compress.zig")}`,
        ...flags,
        `-Mc=${join(work, "c.zig")}`,
        `-femit-bin=${out}`,
        ...caches,
      ],
      { stdio: "inherit", cwd: work },
    );
    const bytes = readFileSync(out);
    const module = await WebAssembly.compile(bytes);
    if (WebAssembly.Module.imports(module).length) {
      throw new Error(
        `compression must import nothing: ${JSON.stringify(WebAssembly.Module.imports(module))}`,
      );
    }

    writeFileSync(
      target,
      `// Generated by packages/compress/build.ts; zlib is under the zlib license, the LZMA SDK in the public domain.\n// inputs: ${inputDigest}\nexport const binary =\n  "${bytes.toString("base64")}";\n`,
    );
    copyFileSync(join(zlib, "LICENSE"), join(here, "LICENSE.zlib"));
    console.log(`compress: ${bytes.length} bytes`);
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

/** Zig on the PATH if it is the pinned version, else the pinned release, downloaded and checked once. */
function findZig(): string {
  try {
    if (execFileSync("zig", ["version"]).toString().trim() === ZIG_VERSION) {
      return "zig";
    }
  } catch {
    // Not on the PATH.
  }

  const platform = `${process.arch === "arm64" ? "aarch64" : "x86_64"}-${process.platform}`;
  const sha256 = ZIG_SHA256[platform];
  if (!sha256 || (process.arch !== "x64" && process.arch !== "arm64")) {
    throw new Error(`put Zig ${ZIG_VERSION} on the PATH to rebuild the compressors`);
  }

  const name = `zig-${platform}-${ZIG_VERSION}`;
  const cache = join(process.env.XDG_CACHE_HOME ?? join(homedir(), ".cache"), "swf2es");
  const zig = join(cache, name, "zig");
  if (existsSync(zig)) {
    return zig;
  }

  mkdirSync(cache, { recursive: true });
  const archive = join(cache, `${name}.tar.xz`);
  execFileSync("curl", [
    "-fsSL",
    "-o",
    archive,
    `https://ziglang.org/download/${ZIG_VERSION}/${name}.tar.xz`,
  ]);
  const actual = createHash("sha256").update(readFileSync(archive)).digest("hex");
  if (actual !== sha256) {
    rmSync(archive);
    throw new Error(`${name}.tar.xz has SHA-256 ${actual}, not ${sha256}`);
  }

  execFileSync("tar", ["-xJf", archive, "-C", cache]);
  rmSync(archive);
  return zig;
}
